	//                 "altname": "ATOM.S",
	//                 "decimals": 8,
	//                 "display_decimals": 6,
	//                 "status": "enabled",
	//             },
	//             "XXBT": {
	//                 "aclass": "currency",
	//                 "altname": "XBT",
	//                 "decimals": 10,
	//                 "display_decimals": 5,
	//                 "margin_rate": 0.01,
	//                 "status": "enabled",
	//             },
	//             "XETH": {
	//                 "aclass": "currency",
	//                 "altname": "ETH",
	//                 "decimals": 10,
	//                 "display_decimals": 5
	//                 "margin_rate": 0.02,
	//                 "status": "enabled",
	//             },
	//             "XBT.M": {
	//                 "aclass": "currency",
	//                 "altname": "XBT.M",
	//                 "decimals": 10,
	//                 "display_decimals": 5
	//                 "status": "enabled",
	//             },
	//             "ETH.M": {
	//                 "aclass": "currency",
	//                 "altname": "ETH.M",
	//                 "decimals": 10,
	//                 "display_decimals": 5
	//                 "status": "enabled",
	//             },
	//             ...
	//         },
