func (this *Kraken) ParseLedgerEntry(item any, optionalArgs ...any) any {
	//
	//     {
	//         'LTFK7F-N2CUX-PNY4SX': {
	//             "refid": "TSJTGT-DT7WN-GPPQMJ",
	//             "time":  1520102320.555,
	//             "type": "trade",
	//             "aclass": "currency",
	//             "asset": "XETH",
	//             "amount": "0.1087194600",
	//             "fee": "0.0000000000",
	//             "balance": "0.2855851000"
	//         },
	//         ...
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var id *string = this.SafeString(item, "id")
	var direction string
	var account any = nil
	var referenceId *string = this.SafeString(item, "refid")
	var referenceAccount any = nil
	var typeVar *string = this.ParseLedgerEntryType(this.SafeString(item, "type"))
	var currencyId *string = this.SafeString(item, "asset")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var currencyResolved map[string]any = this.SafeCurrency(currencyId, currency)
	var amount *string = this.SafeString(item, "amount")
	if Precise.StringLt(amount, "0") {
		direction = "out"
		amount = Precise.StringAbs(amount)
	} else {
		direction = "in"
	}
	var timestamp *int64 = this.SafeIntegerProduct(item, "time", 1000)
	return this.SafeLedgerEntry(map[string]any{
		"info":             item,
		"id":               id,
		"direction":        direction,
		"account":          account,
		"referenceId":      referenceId,
		"referenceAccount": referenceAccount,
		"type":             typeVar,
		"currency":         code,
		"amount":           this.ParseNumber(amount),
		"before":           nil,
		"after":            this.SafeNumber(item, "balance"),
		"status":           "ok",
		"timestamp":        timestamp,
		"datetime":         this.Iso8601(timestamp),
		"fee": map[string]any{
			"cost":     this.SafeNumber(item, "fee"),
			"currency": code,
		},
	}, currencyResolved)
}

