	var response map[string]any = MapTyped(PanicOnError((<-this.PrivatePostLedgers(this.Extend(request, paramsOmitted))).Raw))
	// {  error: [],
	//   "result": { ledger: { 'LPUAIB-TS774-UKHP7X': {   refid: "A2B4HBV-L4MDIE-JU4N3N",
	//                                                   "time":  1520103488.314,
