	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivatePostBalanceEx(params)).Raw))

	//
	//     {
	//         "error": [],
	//         "result": {
