/**
 * @method
 * @name kraken#fetchWithdrawals
 * @description fetch all withdrawals made from an account
 * @see https://docs.kraken.com/api-reference/funding/get-status-of-recent-withdrawals
 * @param {string} code unified currency code
 * @param {int} [since] the earliest time in ms to fetch withdrawals for
 * @param {int} [limit] the maximum number of withdrawals structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest transaction entry
 * @param {int} [params.end] timestamp in seconds of the latest transaction entry
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times
 * @returns {object[]} a list of [transaction structures]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Kraken) FetchWithdrawalsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchWithdrawalsBody(ch, optionalArgs...)
	return ch
}
func (this *Kraken) fetchWithdrawalsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var paginateparamsPaginateVariable []any = this.HandleOptionBoolAndParams(params, "fetchWithdrawals", "paginate", false)
	var paginate bool = GetValueBool(paginateparamsPaginateVariable, 0, false)
	var paramsPaginate map[string]any = MapTyped(GetValue(paginateparamsPaginateVariable, 1))
	if paginate {
		AddElementToObject(paramsPaginate, "cursor", true)

		var retRes320519 []any = ListTyped(PanicOnError((<-this.FetchPaginatedCallCursorAsync("fetchWithdrawals", code, since, limit, paramsPaginate, "next_cursor", "cursor"))))
		ch <- BoxAbsent(retRes320519)
		return nil
	}
	var request map[string]any = map[string]any{}
	if code != nil {
		var currency map[string]any = this.Currency(code)
		request["asset"] = currency["id"]
	}
	if since != nil {
		var sinceString *string = this.NumberToString(since)
		request["start"] = Precise.StringDiv(sinceString, "1000")
	}
	var until *string = this.SafeString2(paramsPaginate, "until", "till")
	var paramsOmitted map[string]any = func() map[string]any {
		if until != nil {
			return MapTyped(this.Omit(paramsPaginate, []any{"until", "till"}))
		}
		return paramsPaginate
	}()
	if until != nil {
		var untilDivided *string = Precise.StringDiv(until, "1000")
		request["end"] = Precise.StringAdd(untilDivided, "1")
	}

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivatePostWithdrawStatus(this.Extend(request, paramsOmitted))).Raw))
	//
	// with no pagination
	//     {  error: [],
	//       "result": [ { "method": "Ether",
	//                     "aclass": "currency",
	//                      "asset": "XETH",
	//                      "refid": "A2BF34S-O7LBNQ-UE4Y4O",
	//                       "txid": "0x298c83c7b0904d8400ef43e1c9e2287b518f7ea3d838822d53f704a1565c274d",
	//                       "info": "0x7cb275a5e07ba943fee972e165d80daa67cb2dd0",
	//                     "amount": "9.9950000000",
	//                        "fee": "0.0050000000",
	//                       "time":  1530481750,
	//                     "status": "Success"                                                             } ] }
	// with pagination
	//    {
	//        "error":[],
	//        "result":{
	//           "withdrawals":[
	//              {
	//                 "method":"Tether USD (TRC20)",
	//                 "aclass":"currency",
	//                 "asset":"USDT",
	//                 "refid":"BSNFZU2-MEFN4G-J3NEZV",
	//                 "txid":"1c7a642fb7387bbc2c6a2c509fd1ae146937f4cf793b4079a4f0715e3a02615a",
	//                 "info":"TQmdxSuC16EhFg8FZWtYgrfFRosoRF7bCp",
	//                 "amount":"1996.50000000",
	//                 "fee":"2.50000000",
	//                 "time":1669126657,
	//                 "status":"Success",
	//                 "key":"poloniex",
	//                 "network":"Tron"
	//              },
	//             ...
	//           ],
	//           "next_cursor":"HgAAAAAAAABGVFRSd3k1LVF4Y0JQY05Gd0xRY0NxenFndHpybkwBAQH2AwEBAAAAAQAAAAAAAAABAAAAAAAZAAAAAAAAAA=="
	//        }
	//     }
	//
	var rawWithdrawals any = nil
	var result any = this.SafeValue(response, "result")
	if !IsArray(result) {
		rawWithdrawals = this.AddPaginationCursorToResult(result)
	} else {
		rawWithdrawals = result
	}

	ch <- this.ParseTransactionsByType("withdrawal", rawWithdrawals, code, since, limit)
	return nil
}
func (this *Kraken) AddPaginationCursorToResult(result any) any {
	var cursor *string = this.SafeString(result, "next_cursor")
	var data any = this.SafeValue(result, "withdrawals")
	var dataLength int = GetArrayLength(data)
	if (cursor != nil) && (dataLength > 0) {
		var last any = GetValue(data, dataLength-1)
		AddElementToObject(last, "next_cursor", cursor)
		AddElementToObject(data, dataLength-1, last)
	}
	return data
}

